site''s images are rock engravings [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include figures with lances [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include ritual dances [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include bullfights [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]; The carvings include camel caravans [SUPPORTED: https://qobustan.jnews.az/en/petroglyphs.html]; The carvings include the sun [SUPPORTED: https://qobustan.jnews.az/en/petroglyphs.html]; The carvings include other stars [SUPPORTED: https://medomed.org/featured_item/gobustan-rock-art-cultural-landscape-azerbaijan/]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 47;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_prov_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'raw_data' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.new_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.old_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_prov_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_prov_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/card-provenance', 'wb-teaser-prov-s047', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card provenance: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'raw_data' THEN u.raw_data IS DISTINCT FROM p.new_value::jsonb
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_prov_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-prov-s047'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-prov-s047'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('raw_data'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card provenance: this run stamp journalled % row(s) outside unified_sites.(raw_data)', bad;
    END IF;

    RAISE NOTICE 'teaser card provenance: % of % planned cell(s) changed and journalled over 47 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-prov-s047'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_prov_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_prov_plan left behind',
       (to_regclass('pg_temp._teaser_prov_plan') IS NOT NULL)::int::text
